    def double_values(value):
        if isinstance(value, (int, float)):
            return value * 2
        elif isinstance(value, list):
            return [double_values(v) for v in value]
        elif isinstance(value, str):
            if re.match(r'^-?\d+(\.\d+)?$', value):
